/// <summary>
/// Extension class for <c>InventTable</c>
/// </summary>
[ExtensionOf(tablestr(InventTable))]
public final class METInventTable_Extension
{
    

}

Method.Source:
    /// <summary>
    /// Get InventTable buffer related to the SalesLine with limited fields
    /// </summary>
    /// <returns>InventTable buffer with limited fields</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public InventTable metInventTableLimitedFields()
    {
        InventTable     metInventTableLimitedFields;
        select firstonly Product, NetWeight, TaraWeight, UnitVolume
            from metInventTableLimitedFields
            where metInventTableLimitedFields.ItemId == this.ItemId;

        return metInventTableLimitedFields;
    }

/// <summary>
/// Get slot location from <c>METReqItemTable</c> table
/// </summary>
/// <param name = "_itemid">_itemid</param>
/// <param name = "_inventlocationId">_inventlocationId</param>
/// <returns>METSlotLoc1Area</returns>
public METSlotLoc1Area getSlotLocation(ItemId _itemid, InventLocationId _inventlocationId)
{
    ReqItemTable reqItemTable;
    METReqItemTable metReqItemTable;
    InventDim inventDimloc;
    
    select firstonly RecId from reqItemTable
            join SlotLoc1Area from metReqItemTable
            where reqItemTable.RecId == metReqItemTable.RefRecId &&
                  reqItemTable.ItemId == _itemid
            join inventDimloc
            where inventDimloc.inventDimId == reqItemTable.CovInventDimId
                && inventDimloc.inventLocationId == _inventlocationId;
    
    return metReqItemTable.SlotLoc1Area;
}

/// <summary>
/// GEt item pack from <c>InventItemSalesSetup</c> table
/// </summary>
/// <param name = "_itemid">_itemid</param>
/// <param name = "_inventSiteId">_inventSiteId</param>
/// <returns>METSalesUnit</returns>
public METSalesUnit getItemPack(ItemId _itemid, InventSiteId _inventSiteId)
{
    InventItemSalesSetup inventItemSalesSetup;
    InventDim inventDimloc;
    
    select firstonly METSalesUnit from inventItemSalesSetup
            where inventItemSalesSetup.ItemId == _itemid
        join RecId from inventDimloc
            where inventDimloc.InventDimId == inventItemSalesSetup.InventDimId
            && inventDimloc.InventSiteId == _inventSiteId;
    
    return inventItemSalesSetup.METSalesUnit;
}

/// <summary>
/// Finds ItemType for the <c>InventTabke</c> record from related <c>METInventItemOrderSetup</c> table
/// </summary>
/// <param name = "_itemid">ItemId</param>
/// <param name = "_inventSiteId">InventSiteId</param>
/// <returns>ItemType</returns>
public static METItemTypes metGetItemType(ItemId            _itemid,   
                                          InventSiteId     _inventSiteId)
{
    return (select firstonly ItemType
            from METInventItemOrderSetup
            where METInventItemOrderSetup.ItemId == _itemid
            && METInventItemOrderSetup.SiteId == _inventSiteId).ItemType;
}

/// <summary>
/// Finds FilterCode1 for the <c>InventTabke</c> record from related <c>METInventItemOrderSetup</c> table
/// </summary>
/// <param name = "_itemid">ItemId</param>
/// <param name = "_inventSiteId">InventSiteId</param>
/// <returns>FilterCode1</returns>
public static METFilterCodeone metGetFilterCodeOne(ItemId            _itemid,
                                                    InventSiteId     _inventSiteId)
{
    return (select firstonly FilterCode
            from METInventItemOrderSetup
            where METInventItemOrderSetup.ItemId == _itemid
            && METInventItemOrderSetup.SiteId == _inventSiteId).FilterCode;
}

    /// <summary>
    /// Get Order split category code for item on the SalesLine.
    /// </summary>
    /// <param name = "_itemid">ItemId</param>
    /// <param name = "_inventDim">InventDim</param>
    /// <returns>Order split category code</returns>
    public static METOSCCode metGetOSCCode(ItemId            _itemid,
                                           InventDim      _inventDim)
    {
        InventDim   metInventDimOSCCode;

        metInventDimOSCCode.InventSiteId        = _inventDim.InventSiteId;
        metInventDimOSCCode.InventLocationId    = _inventDim.InventLocationId;

        metInventDimOSCCode = InventDim::findOrCreate(metInventDimOSCCode);
        ReqItemTable reqItemTable; 
        METReqItemTable metReqItemTable;

        select firstonly OSCCode 
            from metReqItemTable
            exists join reqItemTable
                where reqItemTable.RecId == metReqItemTable.RefRecId
                    && reqItemTable.ItemId == _itemid
                    && reqItemTable.CovInventDimId == metInventDimOSCCode.inventDimId;

        return metReqItemTable.OSCCode;
    }

    /// <summary>
    /// Finds the related <c>METInventTable</c> record
    /// </summary>
    /// <returns><c>METInventTable</c> record buffer</returns>
    public METInventTable metInventTable()
    {
        METInventTable      metInventTable;
        
        select firstonly metInventTable where metInventTable.ItemId == this.ItemId;

        return metInventTable;
    }

/// <summary>
/// Finds the related <c>METInventTable</c> record
/// </summary>
/// <returns>True if records exists; otherwise false</returns>
public boolean metInventTableExists()
{
    return (select firstonly RecId from METInventTable where METInventTable.ItemId == this.ItemId).RecId;
}

/// <summary>
/// Insert record into <c>METInventTable</c>
/// </summary>
public void metInsertMETInventTable()
{
    METInventTable      metInventTable;
    if (!this.metInventTableExists())
    {
        metInventTable.ItemId = this.ItemId;
        metInventTable.insert();
    }
}

    /// <summary>
    /// Method to determine if conversion exists  between the purchase and warehouse units
    /// </summary>
    /// <param name = "_conversionQty">Qty to convert</param>
    /// <param name = "_convertFromUOM">UOM to convert from</param>
    /// <param name = "_itemId">item id</param>
    /// <param name = "_inventLocationId">the warehouse location</param>
    /// <param name = "_inventSiteId">the inventory site</param>
    /// <returns>True if UOM conversion is found/else false and warehouse unit and the warehouse quantity</returns>
    public static container getWarehouseUnitAndQty(Qty _conversionQty, UnitOfMeasureSymbol _convertFromUOM, Itemid _itemId,  
                                                   InventLocationId _inventLocationId, InventSiteId _inventSiteId)
    {
        UnitOfMeasureConversion     unitOfMeasureConversion;
        boolean                     isUnitConversionPresent;
        Qty                         warehouseQty;
        InventTableModule           inventTableModule;
        UnitOfMeasureSymbol         inventoryUnit, warehouseUnit;
        InventLocation              inventLocation;
        METInventLocation           metInventLocation;
        METExtWMSUnit               externalWarehouseUnit;

        InventItemPurchSetup        inventItemPurchSetup;
        InventItemSalesSetup        inventItemSalesSetup;
        InventDim                   inventDim;

        if(!_inventLocationId)
        {
            return [isUnitConversionPresent, _conversionQty, _convertFromUOM];
        }

        select firstonly ExternalWMSUnit from metInventLocation
            join RecId from inventLocation
                where metInventLocation.InventLocation == inventLocation.RecId
                    && inventLocation.InventLocationId == _inventLocationId;

        externalWarehouseUnit = metInventLocation.ExternalWMSUnit;

        switch(externalWarehouseUnit)
        {
            case METExtWMSUnit::DefaultInventoryUnit :
                select firstonly UnitId from inventTableModule
                    where inventTableModule.ItemId      == _itemId
                        && inventTableModule.ModuleType == ModuleInventPurchSales::Invent;

                if(inventTableModule.UnitId)
                {
                    warehouseUnit = inventTableModule.UnitId;
                }
                break;

            case METExtWMSUnit::DefaultPurchaseUnit :

                inventDim.clear();
                inventDim.InventSiteId = _inventSiteId;
                inventDim = InventDim::findDim(inventDim);

                inventItemPurchSetup = InventItemPurchSetup::find(_itemId, inventDim.inventDimId);

                if(inventItemPurchSetup.METPurchUnit)
                {
                    warehouseUnit = inventItemPurchSetup.METPurchUnit;
                }
                break;

            case METExtWMSUnit::DefaultSellUnit :

                inventDim.clear();
                inventDim.InventSiteId = _inventSiteId;
                inventDim = InventDim::findDim(inventDim);

                inventItemSalesSetup = InventItemSalesSetup::find(_itemId, inventDim.inventDimId);
                
                if(inventItemSalesSetup.METSalesUnit)
                {
                    warehouseUnit = inventItemSalesSetup.METSalesUnit;
                }
                break;

            default : 
                return [true, _conversionQty, _convertFromUOM];
        }
             
        
        select firstonly UnitId from inventTableModule
            where inventTableModule.ItemId      == _itemId
                && inventTableModule.ModuleType == ModuleInventPurchSales::Invent;

        if(inventTableModule.UnitId)
        {
            inventoryUnit = inventTableModule.UnitId;
        }

        if(_convertFromUOM == warehouseUnit)
        {
            isUnitConversionPresent = true;
            warehouseQty = _conversionQty;
        }
        else if(warehouseUnit != METConstants::emptyString)
        {
            unitOfMeasureConversion = UnitOfMeasureConversion::findByConversion(
                            UnitOfMeasure::findBySymbol(warehouseUnit).RecId,
                            UnitOfMeasure::findBySymbol(_convertFromUOM).RecId,
                            EcoResProduct::findByProductNumber(_itemId).RecId);

            if(unitOfMeasureConversion.RecId)
            {
                isUnitConversionPresent = true;
                if(_convertFromUOM == inventoryUnit)
                {
                    warehouseQty = _conversionQty / unitOfMeasureConversion.Factor;
                }
                else
                {
                    warehouseQty = _conversionQty * unitOfMeasureConversion.Factor;
                }
            }
            else
            {
                //Check purchase to warehouse conversion
                unitOfMeasureConversion = UnitOfMeasureConversion::findByConversion(
                            UnitOfMeasure::findBySymbol(_convertFromUOM).RecId,
                            UnitOfMeasure::findBySymbol(warehouseUnit).RecId,
                            EcoResProduct::findByProductNumber(_itemId).RecId);

                if(unitOfMeasureConversion.RecId)
                {
                    isUnitConversionPresent = true;
                    if(_convertFromUOM == inventoryUnit)
                    {
                        warehouseQty = _conversionQty / unitOfMeasureConversion.Factor;
                    }
                    else
                    {
                        warehouseQty = _conversionQty * unitOfMeasureConversion.Factor;
                    }
                }
                else
                {
                    isUnitConversionPresent = false;
                }
            }
        }

        return [isUnitConversionPresent, warehouseQty, warehouseUnit];
    }

/// <summary>
/// Insert
/// </summary>
/// <param name = "_doInsert">do insert</param>
public void insert(boolean _doInsert)
{
    next insert(_doInsert);
    this.metInsertMETInventTable();
}

    /// <summary>
    /// CB272 item attributes value
    /// </summary>
    /// <param name = "_category">_category</param>
    /// <returns>AttributeValueText</returns>
    public AttributeValueText metGetProductAttributeforCategory(Name _category)
    {
        InventTable                 inventTable = InventTable::find(this.ItemId);;
        METGetAttributeValue        getAttributeValue;
        AttributeValueText          productAttributeforCategory;
        EcoResProductParameters     ecoResProductParameters = EcoResProductParameters::find();

        if (inventTable.RecId
                && ecoResProductParameters.METConsumerGSTExempt)
        {           
            getAttributeValue = METGetAttributeValue::newFromInventTable(inventTable);
            productAttributeforCategory = getAttributeValue.getAttributeValue(ecoResProductParameters.METConsumerGSTExempt) ? METConstants::Yes : METConstants::No;
        }

        return  productAttributeforCategory;
    }

    /// <summary>
    /// Gets the text attribute value for the product.
    /// </summary>
    /// <param name = "_product"></param>
    /// <param name = "_attibuteRecId"></param>
    /// <returns>Text attribute value</returns>
    public AttributeValueText getProductTextAttribueVal(RecId _attibuteRecId)
    {
        InventTable                 InventTable;
        EcoResProductAttributeValue ecoResProductAttributeValue;
        EcoResAttribute             ecoResAttribute;
        EcoResValue                 ecoResValue;

        select firstonly RecId from InventTable where InventTable.itemid == this.ItemId
            join RecId,Value from ecoResProductAttributeValue
                where ecoResProductAttributeValue.Product == InventTable.Product
            join Name from ecoResAttribute
                where ecoResProductAttributeValue.Attribute == ecoResAttribute.RecId
                && ecoResAttribute.RecId == _attibuteRecId
            join ecoResValue
                where ecoResValue.RecId == ecoResProductAttributeValue.Value;

        return  ecoResValue.value();
    }

    /// <summary>
    /// Gets the boolean attribute value for the product.
    /// </summary>
    /// <param name = "_product"></param>
    /// <param name = "_attibuteRecId"></param>
    /// <returns>Boolean attribute value</returns>
    public AttributeValueBoolean getProductBooleanAttributeVal(RecId _attibuteRecId)
    {
        EcoResProductAttributeValue prodAttrValue;
        EcoResAttribute attribute;
        EcoResProduct product;
        EcoResbooleanvalue  boolValue;

        select firstOnly BooleanValue
            from boolValue
        exists join prodAttrValue
            where prodAttrValue.Value == boolValue.RecId
        exists join product
            where product.RecId == prodAttrValue.Product
               && product.DisplayProductNumber == this.ItemId
        exists join attribute
            where attribute.RecId == prodAttrValue.Attribute
               && attribute.RecId == _attibuteRecId;

        return boolValue.booleanvalue;
    }

    /// <summary>
    /// Updates cached attribute fields on the related <c>METInventTable</c> record using product attribute values.
    /// </summary>
    /// <param name="_ecoResProductParameters">Product parameter record that provides the attribute RecIds to read.</param>
    /// <param name="_displayInfoOnUpdate">Optional flag to log/display attribute changes instead of applying them silently. Defaults to false.</param>   
    public void setAttributeValues(EcoResProductParameters _ecoResProductParameters, METDisplayInfoOnUpdate _displayInfoOnUpdate = false)
    {
        AttributeValueBoolean   pricedByWeight, consumerGSTExempt,tempItemForPackChange;
        AttributeValueText      levyType, invoiceCategory;
        EcoResProduct           ecoResProduct = EcoResProduct::find(this.Product);

        if (ecoResProduct.RecId)
        {
            pricedByWeight =  this.getProductBooleanAttributeVal(_ecoResProductParameters.METPricedByWeight);
            levyType = this.getProductTextAttribueVal(_ecoResProductParameters.METLevyType);
            invoiceCategory = this.getProductTextAttribueVal(_ecoResProductParameters.METInvoiceCategory);
            consumerGSTExempt =  this.getProductBooleanAttributeVal(_ecoResProductParameters.METConsumerGSTExempt);
            tempItemForPackChange =  this.getProductBooleanAttributeVal(_ecoResProductParameters.METTempItemForPackChange);
            // call update only if there is a attribute value change. 
            if(!(ecoResProduct.METPricedByWeight == pricedByWeight
                && ecoResProduct.METLevyType == levyType
                && ecoResProduct.METInvoiceCategory == invoiceCategory
                && ecoResProduct.METConsumerGSTExempt == consumerGSTExempt
                && ecoResProduct.METTempItemForPackChange == tempItemForPackChange))
            {
                if (_displayInfoOnUpdate)
                {
                    if(ecoResProduct.METPricedByWeight != pricedByWeight)
                    {
                        Info(strFmt("@MET:AttributeCacheValueUpdate", this.ItemId, METConstants::PricedByWeightAttributeId, ecoResProduct.METPricedByWeight, pricedByWeight));
                    }

                    if(ecoResProduct.METLevyType != levyType)
                    {
                        Info(strFmt("@MET:AttributeCacheValueUpdate", this.ItemId, METConstants::LevyTypeAttributeId, ecoResProduct.METLevyType, levyType));
                    }

                    if(ecoResProduct.METInvoiceCategory != invoiceCategory)
                    {
                        Info(strFmt("@MET:AttributeCacheValueUpdate", this.ItemId, METConstants::InvoiceCategory, ecoResProduct.METInvoiceCategory, invoiceCategory));
                    }

                    if(ecoResProduct.METConsumerGSTExempt != consumerGSTExempt)
                    {
                        Info(strFmt("@MET:AttributeCacheValueUpdate", this.ItemId, METConstants::ConsumerGSTExempt, ecoResProduct.METConsumerGSTExempt, consumerGSTExempt));
                    }

                    if(ecoResProduct.METTempItemForPackChange != tempItemForPackChange)
                    {
                        Info(strFmt("@MET:AttributeCacheValueUpdate", this.ItemId, METConstants::TempItemForPackChange, ecoResProduct.METTempItemForPackChange, tempItemForPackChange));
                    }
                }

                ecoResProduct.selectForUpdate(true);
                ecoResProduct.skipBusinessEvents(true);
                ecoResProduct.METPricedByWeight =  pricedByWeight;
                ecoResProduct.METLevyType = levyType;
                ecoResProduct.METInvoiceCategory = invoiceCategory;
                ecoResProduct.METConsumerGSTExempt =  consumerGSTExempt;
                ecoResProduct.METTempItemForPackChange = tempItemForPackChange;
                ecoResProduct.METIsAttributeCalculated = NoYes::Yes;
                ecoResProduct.update();                                                        
            }
        }    
    }
